exercises.solution:
class ReadingBuffer
{
public:
    ReadingBuffer(int capacity) : data(new double[capacity]), capacity(capacity), count(0) {}   // acquire
    ~ReadingBuffer() { delete[] data; }                                                       // release
    ReadingBuffer(const ReadingBuffer&) = delete;
    ReadingBuffer& operator=(const ReadingBuffer&) = delete;

    bool add(double v)
    {
        if (count == capacity) return false;
        data[count++] = v;
        return true;
    }
    int size() const { return count; }
    double average() const
    {
        if (count == 0) return 0;
        double sum = 0;
        for (int i = 0; i < count; i++) sum += data[i];
        return sum / count;
    }
private:
    double* data;
    int capacity;
    int count;
};

