exercises.solution:
struct Door
{
    bool locked = false;
    int timesLocked = 0;
};

class LockGuard
{
public:
    LockGuard(Door& d) : door(d)
    {
        door.locked = true;       // acquire
        door.timesLocked++;
    }
    ~LockGuard() { door.locked = false; }   // release, on every way out
    LockGuard(const LockGuard&) = delete;
    LockGuard& operator=(const LockGuard&) = delete;
private:
    Door& door;
};

exercises.prompt:
Wave owns its enemies through raw pointers, and it leaks. Fix it:
- add a destructor that deletes every enemy;
- make void clear() delete every enemy (not just forget them) and leave the wave empty;
- write int totalHealth() const: the sum of all enemies' hp.
spawn and count already work. Enemy has a live counter the tests use.

exercises.starter:
struct Enemy
{
    inline static int alive = 0;
    int hp;
    Enemy(int hp) : hp(hp) { alive++; }
    ~Enemy() { alive--; }
};

class Wave
{
public:
    Wave() {}
    Wave(const Wave&) = delete;
    Wave& operator=(const Wave&) = delete;

    void spawn(int hp) { enemies.push_back(new Enemy(hp)); }
    int count() const { return enemies.size(); }
    int totalHealth() const { return 0; }
    void clear() { enemies.clear(); }   // BUG: the Enemy objects are never deleted
