exercises.solution:
struct Enemy
{
    inline static int alive = 0;
    int hp;
    Enemy(int hp) : hp(hp) { alive++; }
    ~Enemy() { alive--; }
};

class Wave
{
public:
    Wave() {}
    ~Wave() { clear(); }        // the wave owns its enemies, so it releases them
    Wave(const Wave&) = delete;
    Wave& operator=(const Wave&) = delete;

    void spawn(int hp) { enemies.push_back(new Enemy(hp)); }
    int count() const { return enemies.size(); }
    int totalHealth() const
    {
        int total = 0;
        for (const Enemy* e : enemies) total += e->hp;
        return total;
    }
    void clear()
    {
        for (Enemy* e : enemies) delete e;
        enemies.clear();
    }
private:
    std::vector<Enemy*> enemies;
};
